import game.*;import entity.Santa;import java.awt.*;import java.awt.image.BufferedImage;import java.io.*;import javax.imageio.ImageIO;
public class ExistingGroundCapture {
 static BufferedImage scene(int w,int h)throws Exception{var panel=V2TestSupport.playing();panel.setSize(w,h);var f=GamePanel.class.getDeclaredField("santa");f.setAccessible(true);((Santa)f.get(panel)).setPosition(784,816);var im=new BufferedImage(w,h,2);var g=im.createGraphics();panel.paint(g);g.dispose();return im;}
 public static void main(String[]args)throws Exception{var dir=new File("build/existing-ground-restoration");dir.mkdirs();var map=WorldMap.forArea(Area.Type.VILLAGE);var cache=WorldMap.class.getDeclaredField("polished");cache.setAccessible(true);Object previous=cache.get(map);BufferedImage old;try{cache.set(map,util.ImageAssets.load("assets/world/village_clean.png"));old=scene(1100,700);}finally{cache.set(map,previous);}var next=scene(1100,700);ImageIO.write(old,"png",new File(dir,"01-current.png"));ImageIO.write(next,"png",new File(dir,"02-toby-ground-style.png"));var comp=new BufferedImage(2200,734,2);var g=comp.createGraphics();g.setColor(new Color(22,34,45));g.fillRect(0,0,2200,734);g.setColor(Color.WHITE);g.setFont(new Font("Dialog",Font.BOLD,18));g.drawString("CURRENT",20,24);g.drawString("EXISTING TOBY ARTWORK",1120,24);g.drawImage(old,0,34,null);g.drawImage(next,1100,34,null);g.dispose();ImageIO.write(comp,"png",new File(dir,"03-before-after.png"));ImageIO.write(scene(1280,800),"png",new File(dir,"04-wide-gameplay.png"));System.out.println("PASS: four same-camera Last Village ground captures");}
}
